import {BUILDING_EDIT_PLANES,voxelPlaneCells,paintVoxelPlane} from './building-edit-planes.js?v=building-vertical-planes-1';
import {voxelStatistics} from './building-voxels.js?v=building-vertical-planes-1';
import {buildingShapeCells} from './building-shapes.js?v=building-vertical-planes-1';
export function mountBuildingVoxelEditor(root,{get,set}){
 root.innerHTML=`<section id="voxelWorkspace" hidden><p>Edit a horizontal floor or a vertical cross-section. Vertical views show layer 24 at the top and layer 1 at the bottom. Blocks above an erased space stay in place, allowing arches and overhangs. Switching construction methods keeps separate drafts until you choose another building style.</p><div class="block-editor-controls"><label>Edit plane<select id="voxelPlane"><option value="horizontal">Horizontal floor</option><option value="xz">Vertical west–east</option><option value="yz">Vertical north–south</option></select></label><label><span id="voxelPositionLabel">Floor layer (1–24)</span><input id="voxelLevel" type="number" min="1" max="24" step="1" value="1"></label><label>Action<select id="voxelAction"><option value="place">Place blocks</option><option value="erase">Erase blocks</option></select></label><label>Application<select id="voxelShape"><option value="single">Single block</option><option value="line">Line</option><option value="plane">Plane</option></select></label><button id="voxelUndo">Undo layered edit</button><button id="voxelRedo">Redo layered edit</button></div><div id="voxelGrid" role="grid" aria-label="Building layer, north at top" aria-rowcount="10" aria-colcount="10">${Array.from({length:10},(_,y)=>`<div role="row">${Array.from({length:10},(_,x)=>`<button type="button" role="gridcell" data-voxel-index="${y*10+x}" tabindex="${x===0&&y===0?0:-1}"></button>`).join('')}</div>`).join('')}</div><p>Filled square: occupied on this layer. Dot: empty here. Outline: placement preview. Drag then release to place; Shift on release or Escape cancels. Keyboard: Shift+Enter starts, arrows extend, Enter places. Existing surface paint stays assigned by column and side across all layers.</p><p id="voxelStatus" role="status"></p></section>`;
 const $=id=>root.querySelector('#'+id),grid=$('voxelGrid'),undo=[],redo=[];let cells=[...grid.querySelectorAll('[data-voxel-index]')],active=0,pending=null,pointer=null;
 const plane=()=>$('voxelPlane').value||'horizontal';
 const level=()=>Number($('voxelLevel').value)-1,snapshot=()=>[...get().voxels];
 function refresh(){const voxels=get().voxels;$('voxelWorkspace').hidden=!voxels;if(!voxels)return;const p=BUILDING_EDIT_PLANES[plane()],z=level();$('voxelPositionLabel').textContent=p.position;$('voxelLevel').max=p.slices;if(!Number.isInteger(z)||z<0||z>=p.slices){$('voxelStatus').textContent=`Choose a whole position from 1 to ${p.slices}.`;return;}if(cells.length!==p.rows*10){grid.innerHTML=Array.from({length:p.rows},(_,y)=>`<div role="row">${Array.from({length:10},(_,x)=>`<button type="button" role="gridcell" data-voxel-index="${y*10+x}" tabindex="-1"></button>`).join('')}</div>`).join('');cells=[...grid.querySelectorAll('[data-voxel-index]')];active=Math.min(active,cells.length-1);}grid.setAttribute('aria-rowcount',String(p.rows));grid.setAttribute('aria-label',p.label+' building cross-section');grid.dataset.vertical=String(p.rows===24);const layer=voxelPlaneCells(voxels,plane(),z),marked=pending?new Set(buildingShapeCells(pending.kind,pending.start,pending.end,p.rows)):new Set();cells.forEach((cell,i)=>{cell.textContent=layer[i].occupied?'■':'·';cell.tabIndex=i===active?0:-1;cell.setAttribute('aria-label',`Column ${layer[i].x+1}, row ${layer[i].y+1}, layer ${layer[i].z+1}: ${layer[i].occupied?'occupied':'empty'}`);cell.style.background=layer[i].occupied?'#608f88':'#eef1ef';cell.style.color=layer[i].occupied?'#fff':'#17382f';cell.style.boxShadow=marked.has(i)?'inset 0 0 0 3px #d79b00':'';});$('voxelUndo').disabled=!undo.length;$('voxelRedo').disabled=!redo.length;const stats=voxelStatistics(voxels);$('voxelStatus').textContent=`${stats.count} blocks · ${stats.columns} occupied columns · highest layer ${stats.height}. Draft until applied.`;}
 function cancel(){pending=null;pointer=null;refresh();}
 function begin(i){const z=level();if(!Number.isInteger(z)||z<0||z>=BUILDING_EDIT_PLANES[plane()].slices){refresh();return;}pending={start:i,end:i,level:z,plane:plane(),kind:$('voxelShape').value==='plane'?'plane':'line',place:$('voxelAction').value==='place'};refresh();}
 function commit(cancelled=false){const p=pending;pending=null;pointer=null;if(p&&!cancelled){const next=paintVoxelPlane(get().voxels,p.plane,p.level,p.kind,p.start,p.end,p.place);if(next.some((v,i)=>v!==get().voxels[i])){undo.push(snapshot());if(undo.length>20)undo.shift();redo.length=0;set({...get(),voxels:next});}}refresh();}
 $('voxelUndo').onclick=()=>{cancel();if(undo.length){redo.push(snapshot());set({...get(),voxels:undo.pop()});refresh();}};$('voxelRedo').onclick=()=>{cancel();if(redo.length){undo.push(snapshot());set({...get(),voxels:redo.pop()});refresh();}};
 for(const id of ['voxelLevel','voxelAction','voxelShape'])$(id).onchange=cancel;$('voxelLevel').oninput=cancel;$('voxelPlane').onchange=()=>{$('voxelLevel').value=String(Math.min(Math.max(1,Number($('voxelLevel').value)||1),BUILDING_EDIT_PLANES[plane()].slices));cancel();};
 grid.onpointerdown=e=>{if(e.button!==0)return;const cell=e.target.closest('[data-voxel-index]');if(!cell)return;e.preventDefault();active=Number(cell.dataset.voxelIndex);cell.focus({preventScroll:true});pointer=e.pointerId;grid.setPointerCapture(pointer);begin(active);};
 grid.onpointermove=e=>{if(e.pointerId!==pointer||!pending||$('voxelShape').value==='single')return;const cell=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-voxel-index]');if(cell&&grid.contains(cell)){pending.end=Number(cell.dataset.voxelIndex);refresh();}};
 grid.onpointerup=e=>{if(e.pointerId===pointer)commit(e.shiftKey);};grid.onpointercancel=cancel;
 grid.onclick=e=>{if(e.detail!==0)return;const cell=e.target.closest('[data-voxel-index]');if(cell){active=Number(cell.dataset.voxelIndex);begin(active);commit();}};
 grid.onkeydown=e=>{if(e.key==='Escape'&&pending){e.preventDefault();cancel();return;}if(e.key==='Enter'&&(e.shiftKey||pending)){e.preventDefault();if(pending)commit();else begin(active);return;}const moves={ArrowLeft:-1,ArrowRight:1,ArrowUp:-10,ArrowDown:10};if(!(e.key in moves))return;e.preventDefault();const cell=e.target.closest('[data-voxel-index]');if(cell)active=Number(cell.dataset.voxelIndex);const next=active+moves[e.key];if(next<0||next>=cells.length||e.key==='ArrowLeft'&&active%10===0||e.key==='ArrowRight'&&active%10===9)return;active=next;if(pending)pending.end=active;refresh();cells[active].focus();};
 return{refresh,reset(){undo.length=0;redo.length=0;pending=null;pointer=null;refresh();}};
}
